#include <iostream>
using namespace std;
class T {
public:
    static int n;
    T()  { ++n; }
    ~T() { --n; }
};
int T::n = 0;
void f(T x) { cout << T::n << " "; }   // x is a copy of the argument
int main() {
    T a, b;
    f(a);
    cout << T::n;
}

#include <iostream>
using namespace std;
class Arr {
    int d[3] = {4, 5, 6};
public:
    int& at(int i)       { return d[i]; }   // chosen for non-const objects
    int  at(int i) const { return d[i]; }   // chosen for const objects
};
int total(const Arr &a) { return a.at(0) + a.at(1) + a.at(2); }
int main() {
    Arr x;
    x.at(1) = 50;          // OK: the non-const at() returns int&
    cout << total(x);      // inside total, a is const: const at() is used
}

